CREATE TABLE IF NOT EXISTS canon_branches (project_id VARCHAR(32) NOT NULL, branch_id VARCHAR(64) NOT NULL, current_version BIGINT NOT NULL DEFAULT 0, updated_at DATETIME(6) NOT NULL, PRIMARY KEY(project_id,branch_id), CONSTRAINT fk_canon_branch_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS story_entities (id VARCHAR(40) PRIMARY KEY, project_id VARCHAR(32) NOT NULL, entity_type VARCHAR(32) NOT NULL, name VARCHAR(255) NOT NULL, metadata JSON NULL, created_at DATETIME(6) NOT NULL, CONSTRAINT fk_story_entity_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE, INDEX idx_story_entity_type(project_id,entity_type)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS canon_commits (id VARCHAR(40) PRIMARY KEY, project_id VARCHAR(32) NOT NULL, branch_id VARCHAR(64) NOT NULL, version BIGINT NOT NULL, base_version BIGINT NOT NULL, chapter_version_id VARCHAR(32) NOT NULL, message VARCHAR(500) NOT NULL DEFAULT '', approved_by VARCHAR(64) NOT NULL, created_at DATETIME(6) NOT NULL, CONSTRAINT fk_canon_commit_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE, CONSTRAINT fk_canon_commit_version FOREIGN KEY(chapter_version_id) REFERENCES document_versions(id), UNIQUE KEY uk_canon_version(project_id,branch_id,version)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS canon_facts_v2 (id VARCHAR(40) PRIMARY KEY, project_id VARCHAR(32) NOT NULL, branch_id VARCHAR(64) NOT NULL, subject_id VARCHAR(40) NOT NULL, predicate VARCHAR(128) NOT NULL, value_json JSON NOT NULL, valid_from VARCHAR(128) NULL, valid_to VARCHAR(128) NULL, known_by_json JSON NULL, revealed_to_reader_at VARCHAR(128) NULL, certainty VARCHAR(32) NOT NULL, source_version_id VARCHAR(32) NOT NULL, start_offset INT NOT NULL, end_offset INT NOT NULL, canon_commit_version BIGINT NOT NULL, recorded_at DATETIME(6) NOT NULL, CONSTRAINT fk_canon_fact_entity FOREIGN KEY(subject_id) REFERENCES story_entities(id), INDEX idx_canon_fact_subject(project_id,branch_id,subject_id,predicate)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS story_events_v2 (id VARCHAR(40) PRIMARY KEY, project_id VARCHAR(32) NOT NULL, branch_id VARCHAR(64) NOT NULL, story_time VARCHAR(128) NOT NULL, duration VARCHAR(128) NULL, location_id VARCHAR(40) NULL, description TEXT NOT NULL, source_version_id VARCHAR(32) NOT NULL, start_offset INT NOT NULL, end_offset INT NOT NULL, canon_commit_version BIGINT NOT NULL, INDEX idx_story_event_time(project_id,branch_id,story_time)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS event_participants (event_id VARCHAR(40) NOT NULL, entity_id VARCHAR(40) NOT NULL, PRIMARY KEY(event_id,entity_id), CONSTRAINT fk_event_participant_event FOREIGN KEY(event_id) REFERENCES story_events_v2(id) ON DELETE CASCADE, CONSTRAINT fk_event_participant_entity FOREIGN KEY(entity_id) REFERENCES story_entities(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS state_transitions (id VARCHAR(40) PRIMARY KEY, project_id VARCHAR(32) NOT NULL, branch_id VARCHAR(64) NOT NULL, entity_id VARCHAR(40) NOT NULL, field_path VARCHAR(255) NOT NULL, before_json JSON NULL, after_json JSON NULL, story_time VARCHAR(128) NOT NULL, event_id VARCHAR(40) NULL, source_version_id VARCHAR(32) NOT NULL, start_offset INT NOT NULL, end_offset INT NOT NULL, canon_commit_version BIGINT NOT NULL, CONSTRAINT fk_state_transition_entity FOREIGN KEY(entity_id) REFERENCES story_entities(id), CONSTRAINT fk_state_transition_event FOREIGN KEY(event_id) REFERENCES story_events_v2(id), INDEX idx_state_transition_lookup(project_id,branch_id,entity_id,field_path,canon_commit_version)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS outbox_events (id VARCHAR(40) PRIMARY KEY, project_id VARCHAR(32) NOT NULL, event_type VARCHAR(80) NOT NULL, aggregate_id VARCHAR(40) NOT NULL, payload JSON NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', attempts INT NOT NULL DEFAULT 0, available_at DATETIME(6) NOT NULL, created_at DATETIME(6) NOT NULL, processed_at DATETIME(6) NULL, INDEX idx_outbox_delivery(status,available_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
